            t.check("talkToLadyOfLake-dialog", pi - 1 == #picks, "picks used " .. (pi - 1) .. " of " .. #picks .. "; " .. trail:sub(1, 500))
            t.ticks(2)
        end
        do
            local vr, vv = t.var.server("varp5761_excalibur_components_progress")
            t.check("lady.started_bit", vr == "ok" and type(vv) == "number" and math.floor(vv / 4) % 2 == 1, "excalibur_started bit (bit2) in " .. tostring(vv))
        end

        -- enterSarimShopAndTalk
        t.exec("goto-enterSarimShopAndTalk", t.player.goto_tile, 3018, 3246, 0)
        t.exec("enterSarimShopAndTalk", t.player.click_loc, "jewellersdoor", 1)

        do
            local picks, pi, trail = {"/No I don't have any bread/"}, 1, ""
            for _ = 1, 8 do
                if t.chat.kind() ~= "none" then break end
                t.ticks(1)
            end
            for _ = 1, 12 do
                local dr, dk = t.chat.drain({ stop_at = "options", max_pages = 60 })
                trail = trail .. "drain->" .. tostring(dr) .. "/" .. tostring(dk) .. " | "
                if t.chat.kind() ~= "options" then break end
                local sel = picks[pi]
                pi = pi + 1
                if sel == nil then
                    t.check("beggar.first.choose", false, "no pick left for an options page; " .. trail)
                    break
                end
                local cr, cd = t.chat.choose(sel)
                trail = trail .. "choose:" .. sel .. "=" .. tostring(cr) .. " | "
                if cr ~= "ok" then
                    t.check("beggar.first.choose", false, tostring(cr) .. " " .. tostring(cd))
                    break
                end
            end
            t.check("beggar.first", pi - 1 == #picks, "picks used " .. (pi - 1) .. " of " .. #picks .. "; " .. trail:sub(1, 500))
            t.ticks(2)
        end
        do
            local vr, vv = t.var.server("varp5761_excalibur_components_progress")
            t.check("beggar.spoken_bit", vr == "ok" and type(vv) == "number" and math.floor(vv / 8) % 2 == 1, "excalibur_spoken_beggar bit (bit3) in " .. tostring(vv))
        end

        -- talkToBeggar with the bread
        t.exec("goto-talkToBeggar", t.player.goto_tile, 3016, 3246, 0)
        t.exec("talkToBeggar", t.player.talk_to, "lake_beggar", 1)

        do
            local picks, pi, trail = {"/Yes, here you go/"}, 1, ""
            for _ = 1, 8 do
                if t.chat.kind() ~= "none" then break end
                t.ticks(1)
            end
            for _ = 1, 12 do
                local dr, dk = t.chat.drain({ stop_at = "options", max_pages = 60 })
                trail = trail .. "drain->" .. tostring(dr) .. "/" .. tostring(dk) .. " | "
                if t.chat.kind() ~= "options" then break end
                local sel = picks[pi]
                pi = pi + 1
                if sel == nil then
                    t.check("talkToBeggar-dialog.choose", false, "no pick left for an options page; " .. trail)
                    break
                end
                local cr, cd = t.chat.choose(sel)
                trail = trail .. "choose:" .. sel .. "=" .. tostring(cr) .. " | "
                if cr ~= "ok" then
                    t.check("talkToBeggar-dialog.choose", false, tostring(cr) .. " " .. tostring(cd))
                    break
                end
            end
            t.check("talkToBeggar-dialog", pi - 1 == #picks, "picks used " .. (pi - 1) .. " of " .. #picks .. "; " .. trail:sub(1, 500))
            t.ticks(2)
        end
        t.exec("excalibur-held", t.inv.await, "excalibur", 1, 6)
        do
            local vr, vv = t.var.server("varp5761_excalibur_components_progress")
            t.check("beggar.rewarded_bit", vr == "ok" and type(vv) == "number" and math.floor(vv / 16) % 2 == 1, "excalibur_rewarded bit (bit4) in " .. tostring(vv))
        end

        -- returnToCamelot: through the gate south of the castle
        t.exec("goto-returnToCamelot", t.player.goto_tile, 2758, 3478, 0)
        t.exec("returnToCamelot", t.player.click_loc, "kr_camelot_metalgateclosedr", 1)

        -- goStandInStar, dropBatBones (Camelot magic symbol), sayWords
        t.exec("goto-goStandInStar", t.player.goto_tile, 2779, 3515, 0)
        t.exec("dropBatBones", t.player.inv_op, "bat_bones", 5)

        do
            local picks, pi, trail = {"/Snarthon Candtrick Termanto/"}, 1, ""
            for _ = 1, 8 do
                if t.chat.kind() ~= "none" then break end
                t.ticks(1)
            end
            for _ = 1, 12 do
                local dr, dk = t.chat.drain({ stop_at = "options", max_pages = 60 })
                trail = trail .. "drain->" .. tostring(dr) .. "/" .. tostring(dk) .. " | "
                if t.chat.kind() ~= "options" then break end
                local sel = picks[pi]
                pi = pi + 1
                if sel == nil then
                    t.check("sayWords.choose", false, "no pick left for an options page; " .. trail)
                    break
                end
                local cr, cd = t.chat.choose(sel)
                trail = trail .. "choose:" .. sel .. "=" .. tostring(cr) .. " | "
                if cr ~= "ok" then
                    t.check("sayWords.choose", false, tostring(cr) .. " " .. tostring(cd))
                    break
                end
            end
            t.check("sayWords", pi - 1 == #picks, "picks used " .. (pi - 1) .. " of " .. #picks .. "; " .. trail:sub(1, 500))
            t.ticks(2)
        end
        t.ticks(2)
        t.exec("quest.stage.excalibur_bound", t.quest.expect_stage, "excalibur_bound")
        do
            local vr, vv = t.var.server("varp5761_excalibur_components_progress")
            t.check("bound.bits_cleared", vr == "ok" and type(vv) == "number" and vv % 4 == 0, "chaosaltar+blackcandle bits cleared in " .. tostring(vv))
        end

        -- goUpLadder1Camelot, goUpLadder2Camelot
        t.exec("goUpLadder1Camelot", t.player.goto_tile, 2769, 3493, 1)
        do local r, tl = t.world.tile(); t.check("cam.level1", r == "ok" and tl.level == 1, "tile " .. (r == "ok" and (tl.x .. "," .. tl.z .. "," .. tl.level) or tostring(tl))) end
        t.exec("goUpLadder2Camelot", t.player.goto_tile, 2768, 3494, 2)
        do local r, tl = t.world.tile(); t.check("cam.level2", r == "ok" and tl.level == 2, "tile " .. (r == "ok" and (tl.x .. "," .. tl.z .. "," .. tl.level) or tostring(tl))) end

        -- smashCrystal with Excalibur
        do
            local crystal = t.player.by_symbol("loc", "merlins_crystal")
            t.exec("smashCrystal", t.player.use_on, "excalibur", crystal)
        end

        do
            local picks, pi, trail = {}, 1, ""
            for _ = 1, 8 do
                if t.chat.kind() ~= "none" then break end
                t.ticks(1)
            end
            for _ = 1, 12 do
                local dr, dk = t.chat.drain({ stop_at = "options", max_pages = 60 })
                trail = trail .. "drain->" .. tostring(dr) .. "/" .. tostring(dk) .. " | "
                if t.chat.kind() ~= "options" then break end
                local sel = picks[pi]
                pi = pi + 1
                if sel == nil then
                    t.check("smashCrystal-dialog.choose", false, "no pick left for an options page; " .. trail)
                    break
                end
                local cr, cd = t.chat.choose(sel)
                trail = trail .. "choose:" .. sel .. "=" .. tostring(cr) .. " | "
                if cr ~= "ok" then
                    t.check("smashCrystal-dialog.choose", false, tostring(cr) .. " " .. tostring(cd))
                    break
                end
            end
            t.check("smashCrystal-dialog", pi - 1 == #picks, "picks used " .. (pi - 1) .. " of " .. #picks .. "; " .. trail:sub(1, 500))
            t.ticks(2)
        end
        t.ticks(2)
        t.exec("quest.stage.freed_merlin", t.quest.expect_stage, "freed_merlin")

        -- finishQuest
        t.exec("goto-finishQuest", t.player.goto_tile, 2764, 3513, 0)
        local reward_excalibur_before_result, reward_excalibur_before = t.inv.count("excalibur")
        t.exec("finishQuest", t.player.talk_to, "king_arthur", 1)

        do
            local picks, pi, trail = {}, 1, ""
            for _ = 1, 8 do
                if t.chat.kind() ~= "none" then break end
                t.ticks(1)
            end
            for _ = 1, 12 do
                local dr, dk = t.chat.drain({ stop_at = "options", max_pages = 60 })
                trail = trail .. "drain->" .. tostring(dr) .. "/" .. tostring(dk) .. " | "
                if t.chat.kind() ~= "options" then break end
                local sel = picks[pi]
                pi = pi + 1
                if sel == nil then
                    t.check("finishQuest-dialog.choose", false, "no pick left for an options page; " .. trail)
                    break
                end
                local cr, cd = t.chat.choose(sel)
                trail = trail .. "choose:" .. sel .. "=" .. tostring(cr) .. " | "
                if cr ~= "ok" then
                    t.check("finishQuest-dialog.choose", false, tostring(cr) .. " " .. tostring(cd))
                    break
                end
            end
            t.check("finishQuest-dialog", pi - 1 == #picks, "picks used " .. (pi - 1) .. " of " .. #picks .. "; " .. trail:sub(1, 500))
            t.ticks(2)
        end
        t.ticks(6)
        t.quest.expect_complete()

        local reward_excalibur_after_result, reward_excalibur_after = t.inv.count("excalibur")
        t.check("reward.excalibur", reward_excalibur_before_result == "ok" and reward_excalibur_after_result == "ok" and reward_excalibur_after >= 1,
            string.format("excalibur %s -> %s (want it held at the end)", tostring(reward_excalibur_before), tostring(reward_excalibur_after)))

        t.finish(0)
    end,
}
